  ("चकराता देहरादून से कितनी दूर है?", "रास्ते के हिसाब से लगभग 87 से 98 किमी।"),
  ("क्या धनौल्टी देहरादून जिले में है?", "नहीं, धनौल्टी टिहरी गढ़वाल जिले में है।"),
